      .post("/produtos")
      .set("authorization", token)
      .send({
        nome: "Produto A",
        preco: 10,
        descricao: "Desc",
        quantidade: 5
      });

    const prod2Res = await request(app)
      .post("/produtos")
      .set("authorization", token)
      .send({
        nome: "Produto B",
        preco: 20,
        descricao: "Desc",
        quantidade: 5
